import{_ as t,o,c as a,a5 as p}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"父子生命周期","description":"Vue 的父组件和子组件的生命周期钩子函数的执行顺序是非常有规律的。以下是在 Vue 组件层级关系中，父组件和子组件生命周期钩子函数的执行顺序： 创建阶段 ： 父：beforeCreate 父：created 父：beforeMount 子：beforeCreate 子：crea。","frontmatter":{"title":"父子生命周期","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","响应式与组合式 API"],"description":"Vue 的父组件和子组件的生命周期钩子函数的执行顺序是非常有规律的。以下是在 Vue 组件层级关系中，父组件和子组件生命周期钩子函数的执行顺序： 创建阶段 ： 父：beforeCreate 父：created 父：beforeMount 子：beforeCreate 子：crea。","sidebarWeight":161,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/生命周期/父子生命周期.md"},"headers":[],"relativePath":"posts/Vue系统教程/03-响应式与组合式 API/父子生命周期.md","filePath":"posts/Vue系统教程/03-响应式与组合式 API/父子生命周期.md"}'),r={name:"posts/Vue系统教程/03-响应式与组合式 API/父子生命周期.md"};function l(d,e,n,i,u,s){return o(),a("div",null,[...e[0]||(e[0]=[p('<div><h1 id="父子生命周期" tabindex="-1">父子生命周期 <a class="header-anchor" href="#父子生命周期" aria-label="Permalink to &quot;父子生命周期&quot;">​</a></h1><blockquote><p>本节目标：理解“父子生命周期”的核心思路，并能把它用于实际开发或面试表达。 Vue 的父组件和子组件的生命周期钩子函数的执行顺序是非常有规律的。以下是在 Vue 组件层级关系中，父组件和子组件生命周期钩子函数的执行顺序：</p></blockquote><ul><li><strong>创建阶段</strong>： <ul><li>父：beforeCreate</li><li>父：created</li><li>父：beforeMount</li><li>子：beforeCreate</li><li>子：created</li><li>子：beforeMount</li><li>子：mounted</li><li>父：mounted</li></ul></li><li><strong>更新阶段</strong>： <ul><li>父：beforeUpdate</li><li>子：beforeUpdate</li><li>子：updated</li><li>父：updated</li></ul></li><li><strong>销毁阶段</strong>： <ul><li>父：beforeDestroy</li><li>子：beforeDestroy</li><li>子：destroyed</li><li>父：destroyed</li></ul></li></ul><p>注意点：</p><ul><li>当 Vue 实例开始挂载时，父组件的 beforeMount 钩子首先被调用，然后是子组件的整个生命周期，直到子组件 mounted 钩子被调用，之后父组件的 mounted 钩子被调用。</li><li>当 Vue 实例或数据更新时，父组件的 beforeUpdate 钩子首先被调用，然后是子组件的 beforeUpdate 钩子，接着是子组件的 updated 钩子，最后是父组件的 updated 钩子。</li><li>在销毁过程中，首先是父组件的beforeDestroy 钩子被调用，然后是子组件的整个销毁生命周期，从beforeDestroy 到destroyed，最后是父组件的destroyed 钩子。</li></ul><p>当 Vue 实例或数据更新时，子组件是否走生命周期（特别是 beforeUpdate 和 updated 钩子）取决于子组件自身的数据是否发生变化。</p><p>如果子组件的 prop 或本地数据发生了改变，那么子组件的 beforeUpdate 和 updated 钩子将会被调用。</p><p>如果仅仅是父组件的数据发生了改变，而这些数据并没有被传递给子组件（即子组件的 prop 和本地数据都没有变化），那么子组件的 beforeUpdate 和 updated 钩子不会被调用。</p><p>以下是一个简单的例子：</p><p>父组件 vue Copy code &lt;template&gt; &lt;div&gt; &lt;button @click=&quot;updateParentData&quot;&gt;Update Parent Data&lt;/button&gt; &lt;child-component :someProp=&quot;parentData&quot;&gt;&lt;/child-component&gt; &lt;/div&gt; &lt;/template&gt;</p><p>&lt;script&gt; import ChildComponent from &#39;./ChildComponent.vue&#39;;</p><p>export default { components: { ChildComponent }, data() { return { parentData: &#39;initial&#39; }; }, methods: { updateParentData() { this.parentData = &#39;updated&#39;; } } }; &lt;/script&gt; 子组件 vue Copy code &lt;template&gt; &lt;div&gt; {{ someProp }} &lt;/div&gt; &lt;/template&gt;</p><p>&lt;script&gt; export default { props: [&#39;someProp&#39;], beforeUpdate() { console.log(&#39;Child beforeUpdate&#39;); }, updated() { console.log(&#39;Child updated&#39;); } }; &lt;/script&gt; 在这个例子中，当你点击“Update Parent Data”按钮后：</p><p>父组件的 beforeUpdate 和 updated 钩子会被调用。 因为 parentData 是作为 prop 传递给子组件的，子组件的 someProp 发生了改变，所以子组件的 beforeUpdate 和 updated 钩子也会被调用。 但如果 parentData 并没有传给子组件，那么点击按钮后，子组件的 beforeUpdate 和 updated 钩子就不会被调用。</p><p>在 React 中，组件的生命周期有一些不同的钩子（或称为生命周期方法）和行为方式。React 的函数组件通常使用 Hooks 如 useEffect 来管理副作用和组件的生命周期，而类组件则使用诸如 componentDidMount、componentDidUpdate 和 componentWillUnmount 等生命周期方法。</p><p>React 父子组件更新 如果父组件重新渲染，它的所有子组件都会进行重新渲染，除非子组件通过 React.memo() 或 shouldComponentUpdate 进行了性能优化。</p><p>函数组件中的 useEffect Hook 或类组件中的 componentDidUpdate 通常用来执行组件更新后的副作用。</p><p>在 React 中，如果父组件的 state 或 props 更新，子组件默认也会重新渲染。但这与 Vue 不同，Vue 更加智能地追踪依赖，只有当子组件的相关 props 或自身的状态改变时，子组件才会更新。</p><p>示例 React 父组件 jsx Copy code import React, { useState } from &#39;react&#39;; import ChildComponent from &#39;./ChildComponent&#39;;</p><p>const ParentComponent = () =&gt; { const [parentData, setParentData] = useState(&#39;initial&#39;);</p><p>const updateParentData = () =&gt; { setParentData(&#39;updated&#39;); };</p><p>return ( &lt;div&gt; &lt;button onClick={updateParentData}&gt;Update Parent Data&lt;/button&gt; &lt;ChildComponent someProp={parentData} /&gt; &lt;/div&gt; ); };</p><p>export default ParentComponent; React 子组件 jsx Copy code import React, { useEffect } from &#39;react&#39;;</p><p>const ChildComponent = ({ someProp }) =&gt; { useEffect(() =&gt; { console.log(&#39;Child component updated&#39;); }, [someProp]);</p><p>return &lt;div&gt;{someProp}&lt;/div&gt;; };</p><p>export default ChildComponent; 在这个例子中：</p><p>当你点击“Update Parent Data”按钮后，父组件会重新渲染。 因为 parentData 是作为 prop 传递给子组件的，子组件的 useEffect 也会触发。 如果你想避免不必要的子组件更新，你可以使用 React.memo 或在类组件中使用 shouldComponentUpdate 方法来进行优化。</p><p>总体而言，React 和 Vue 的组件生命周期有相似之处，但具体的实现和优化方式有所不同。</p></div>',1)])])}const f=t(r,[["render",l]]);export{m as __pageData,f as default};
